function hGlass(x,y,w){
 const panels=Math.max(1,Math.round(w/220));
 return `<g class="om-glass-wall"><rect x="${x+2}" y="${y+1}" width="${Math.max(1,w-4)}" height="3" rx="1.5" fill="#366b82" opacity=".07"/><rect x="${x}" y="${y-19}" width="${w}" height="20" rx="1.5" fill="url(#glass)" stroke="#9fbdc9" stroke-opacity=".48" stroke-width=".8"/><path d="M${x+1} ${y-18}h${w-2}" stroke="#ffffff" stroke-opacity=".95" stroke-width="1.5"/><path d="M${x} ${y}h${w}" stroke="#82a8b9" stroke-opacity=".64" stroke-width="1.3"/>${Array.from({length:panels-1},(_,i)=>`<path d="M${x+(i+1)*w/panels} ${y-18}v17" stroke="#9cb9c5" stroke-opacity=".43" stroke-width=".7"/>`).join('')}<path d="M${x+4} ${y-10}h${Math.max(0,w-8)}" stroke="#ffffff" stroke-opacity=".36" stroke-width="2"/></g>`;
}
function vGlass(x,y,h){
